static int wait_for_key(void)
{
  SDL_Event event;
  while (1)
    {
      while ( SDL_PollEvent(&event) >= 1 ) 
	{
	  switch (event.type) 
	    {
	    case SDL_QUIT: 
	      exit(EXIT_SUCCESS);
	      break;
	    case SDL_KEYDOWN:
	      return event.key.keysym.sym;
	      break;
	    default:
	      break;
	    }
	}
      SDL_Delay(sprite_global.display_dt);
    }
}

